(function(root){'use strict';const H=typeof module==='object'?require('./engine.js'):root.Horar;
function validPlace(p){if(!p)return null;if(typeof p!== 'object'||!Number.isFinite(p.lat)||!Number.isFinite(p.lon)||typeof p.timezone!=='string')throw Error('Некорректное место.');try{new Intl.DateTimeFormat('en',{timeZone:p.timezone});}catch{throw Error('Некорректный часовой пояс.');}return {name:String(p.name||'').slice(0,180),country:String(p.country||'').slice(0,2),region:String(p.region||'').slice(0,180),lat:p.lat,lon:p.lon,timezone:p.timezone};}
function normalize(record){if(!record||typeof record!=='object'||!record.input)throw Error('Некорректная запись.');H.validate(record.input);const i=record.input;if(!Number.isFinite(i.offset)||i.offset< -12||i.offset>14||typeof record.outcome!=='string'||record.outcome.length>3000||typeof record.id!=='string'||!/^[a-zA-Z0-9-]{1,80}$/.test(record.id))throw Error('Некорректные поля записи.');const utc=new Date(i.utc).toISOString();return {id:record.id,input:{question:i.question.trim(),utc,local:new Date(+new Date(utc)+i.offset*3600000).toISOString().slice(0,16),offset:i.offset,place:validPlace(i.place),manualZone:i.manualZone===true,city:typeof i.city==='string'&&/^[a-z]+$/.test(i.city)?i.city:'custom',lat:i.lat,lon:i.lon,system:i.system,target:i.target,...([2,3].includes(i.analysisVersion)?{analysisVersion:i.analysisVersion,topicMode:i.topicMode==='auto'?'auto':'manual',actorInput:['auto','1','3','5','7','11'].includes(String(i.actorInput))?String(i.actorInput):'auto',horizon:i.horizon===90?90:30}:{})},outcome:record.outcome,created:typeof record.created==='string'?record.created:utc};}
function parse(text){const data=JSON.parse(text);if(data?.format!=='horar-journal'||data.version!==1||!Array.isArray(data.entries)||data.entries.length>500)throw Error('Нужен экспорт журнала Хорар (до 500 записей).');return data.entries.map(normalize);}
function key(i){return JSON.stringify([i.question.trim(),new Date(i.utc).toISOString(),i.lat,i.lon,i.system,i.target,[2,3].includes(i.analysisVersion)?i.analysisVersion:1,[2,3].includes(i.analysisVersion)?i.topicMode:null,[2,3].includes(i.analysisVersion)?i.actorInput:null,[2,3].includes(i.analysisVersion)?i.horizon:null]);}
function merge(existing,incoming){const ids=new Set(existing.map(e=>e.id)),keys=new Set(existing.map(e=>key(e.input))),add=[];for(const e of incoming){if(ids.has(e.id)||keys.has(key(e.input)))continue;ids.add(e.id);keys.add(key(e.input));add.push(e);}if(add.length+existing.length>500)throw Error('Журнал ограничен 500 картами. Сначала экспортируйте и удалите ненужные записи.');return {entries:[...add,...existing],added:add.length};}
const api={normalize,parse,key,merge};if(typeof module==='object')module.exports=api;else root.HorarJournal=api;
})(typeof globalThis!=='undefined'?globalThis:this);
